const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={goal:'完成作品集项目介绍',todos:[{text:'整理作品集',done:false},{text:'阅读半小时',done:false},{text:'出去散步',done:false}],note:'',tomorrow:'',history:[]};try{Object.assign(state,JSON.parse(localStorage.getItem('vintage-car-preview')||'{}'))}catch{}let end=0,active='';function save(){try{localStorage.setItem('vintage-car-preview',JSON.stringify(state))}catch{}}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}function goal(){const h=new Date().getHours();$('#hour').textContent=`${String(h).padStart(2,'0')}:00 — ${String(h+1).padStart(2,'0')}:00`;$('#goalText').textContent=state.goal;$('#returnTask').textContent=state.goal}goal();setInterval(goal,60000);function show(html){$('#modal').classList.remove('album-modal','journal-modal','drawer-modal');$('#content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{if(!end)$('#car').classList.remove('shifting')});$('#drive').onclick=()=>{if(end){toast('先完成临时任务，再回到 D 挡');return}$('#car').classList.remove('shifting');$('#modal').close()};$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};$('#stop').onclick=()=>{if(end){toast('已经停靠，先完成眼前这件事');return}$('#car').classList.add('shifting');show('<small>P · 已挂入停车挡</small><h2>先停一会儿。</h2><p>把临时要做的事放在这里，原来的目标会等你回来。</p><form id="intent"><input name="task" placeholder="比如：点外卖" required maxlength="60"><label>预计分钟数<input name="minutes" type="number" min="1" max="180" value="5" required></label><button>开始这段专注</button></form>');$('#intent').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);active=d.get('task');end=Date.now()+Number(d.get('minutes'))*60000;$('#intentTitle').textContent=active;$('#modal').close();window.parkMotion?.();$('#goal').hidden=true;$('#status').textContent='已停靠 · 把注意力留给此刻';tick()}};function tick(){if(!end)return;const t=Math.max(0,Math.ceil((end-Date.now())/1000));$('#clock').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;if(!t)$('#status').textContent='时间到了 · 可以完成或延长'}setInterval(tick,500);$('#extend').onclick=()=>{end=Math.max(Date.now(),end)+300000;tick()};$('#finish').onclick=()=>{state.history.push({hour:new Date().getHours(),text:active});save();end=0;window.resumeMotion?.();$('#goal').hidden=false;$('#status').textContent='沿着今天，慢慢前行';toast('欢迎回来，继续刚才的目标。')};$('#edit').onclick=()=>window.openTvEditor?.();function panel(type){if(type==='album'){
const h=new Date().getHours();show('<div class="album-heading"><small>COLLECT THE LITTLE MOMENTS</small><h2>今日 · 旅途相册</h2><p>把走过的每一小时，留成一页风景。</p><button id="all">展开全天 24h</button></div><div id="hours" class="photo-hours"></div>');$('#modal').classList.add('album-modal');let all=false;
const render=()=>{$('#hours').innerHTML=Array.from({length:24},(_,i)=>i).filter(i=>all||Math.abs(i-h)<3).map((i,n)=>{const records=state.history.filter(x=>x.hour===i);const title=i===h?state.goal:records.length?records[0].text:i<h?'留下一段今天':'给未来留一点空白';const photos=['road','window','book','drawer'];return `<details class="photo-hour" style="--photo:url('assets/${photos[n%photos.length]}.png');--position:${30+(n%3)*20}%"><summary><span class="photo-time">${String(i).padStart(2,'0')}:00 — ${String(i+1).padStart(2,'0')}:00</span><span class="photo-title">${esc(title)}</span><span class="photo-caption">${i===h?'此刻 · 正在发生':i<h?'走过的时间':'前方的时光'}</span><span class="photo-index">${String(i+1).padStart(2,'0')} / 24 <b>＋</b></span></summary><div class="photo-record"><p>${records.map(x=>esc(x.text)+' ✓').join('<br>')||'还没有记录。风景为示意图片，不代表实际活动。'}</p>${i===h?'<button id="album-edit">更换当前小时任务 ↗</button>':''}</div></details>`}).join('');const edit=$('#album-edit');if(edit)edit.onclick=()=>$('#edit').click()};render();$('#all').onclick=()=>{all=!all;$('#all').textContent=all?'收起全天':'展开全天 24h';render()}}
if(type==='todo'){show('<div class="drawer-paper"><small>THINGS FOR TODAY</small><h2>今日待办</h2><p class="note">把想做的事，收在这一张纸上。</p><div id="todos"></div><form id="add" class="line"><input name="text" placeholder="放入一件想做的事" required maxlength="80"><button aria-label="添加待办">＋</button></form></div>');$('#modal').classList.add('drawer-modal');const render=()=>{$('#todos').innerHTML=state.todos.map((t,i)=>`<label><input type="checkbox" data-i="${i}" ${t.done?'checked':''}>${esc(t.text)}</label>`).join('');$('#todos').onchange=e=>{state.todos[e.target.dataset.i].done=e.target.checked;save()}};render();$('#add').onsubmit=e=>{e.preventDefault();state.todos.push({text:new FormData(e.target).get('text'),done:false});save();e.target.reset();render()}}if(type==='journal'){show(`<div class="desk-title"><small>NOTES FROM THE ROAD</small><h2>旅行手帐</h2><p>把今天收好，为明天留一页。</p></div><div class="open-journal"><section class="journal-leaf leaf-left"><small>今日 / 回望</small><h3>今天的足迹</h3><label for="note">今天做了什么，又有什么小小的发现？</label><textarea id="note" placeholder="从一个平凡的瞬间写起…">${esc(state.note)}</textarea><button id="saveNote">收下今天的记录</button><span class="folio">— 01 —</span></section><section class="journal-leaf leaf-right"><small>明日 / 出发</small><h3>下一段旅程</h3><label for="journalPlan">写下明天想做的事与时间</label><textarea id="journalPlan" placeholder="09:00 整理作品集\n12:00 午餐\n15:00 阅读">${esc(state.tomorrow)}</textarea><button id="fileJournal">确认 · 放进明日抽屉</button><span class="folio">— 02 —</span></section></div><p class="journal-disclaimer">文字保存在本机 · 语音识别与 AI 规划尚未接入</p>`);$('#modal').classList.add('journal-modal');$('#saveNote').onclick=()=>{state.note=$('#note').value;state.tomorrow=$('#journalPlan').value;save();toast('今天的足迹，已写进手帐')};$('#fileJournal').onclick=()=>{state.note=$('#note').value;state.tomorrow=$('#journalPlan').value;save();$('.open-journal').classList.add('filed');setTimeout(()=>{$('#modal').close();toast('明日的计划纸，已收进抽屉')},650)}}
if(type==='tomorrow'){show(`<small>A NEW PAGE</small><h2>明日计划</h2><textarea id="planText" placeholder="09:00 整理作品集\n12:00 午餐\n15:00 阅读">${esc(state.tomorrow)}</textarea><p class="note">手动确认安排后，将这张计划纸放进明日抽屉。</p><button id="file">确认 · 放进抽屉</button>`);$('#file').onclick=()=>{state.tomorrow=$('#planText').value;save();$('#modal').close();toast('明日的计划纸，已收进抽屉')}}}document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>panel(b.dataset.panel));

$('#goal').setAttribute('role','button');$('#goal').setAttribute('tabindex','0');$('#goal').setAttribute('aria-label','编辑当前小时任务');$('#goal').onclick=e=>{if(e.target!==$('#edit'))$('#edit').click()};$('#goal').onkeydown=e=>{if(e.target===$('#goal')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();$('#edit').click()}};

window.tvTask={read:()=>state.goal,write:value=>{state.goal=value;save();goal();}};

window.voiceJournal={append:text=>{state.note=(state.note?state.note+'\n\n':'')+text;save();}};

